using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, data structures, and software engineering." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Explore pure and applied mathematics including calculus, algebra, and statistics." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Investigate the fundamental laws governing matter, energy, and the universe." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Develop critical reading, writing, and analytical skills through literature and composition." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examine pivotal events, cultures, and ideas that have shaped the modern world." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "Study living organisms, their structures, functions, evolution, and ecosystems." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Email = "achen@university.edu", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers in top-tier conferences and holds three patents in neural network optimization. She received her Ph.D. from MIT and has been teaching for 15 years.", OfficeLocation = "Science Building 301" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor", Email = "rmartinez@university.edu", Bio = "Dr. Martinez is an expert in abstract algebra and number theory. His research focuses on cryptographic applications of algebraic structures. He is the recipient of the University Teaching Excellence Award.", OfficeLocation = "Math Hall 210" },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor", Email = "sjohnson@university.edu", Bio = "Dr. Johnson researches quantum mechanics and particle physics. She has worked at CERN and contributed to the discovery of new subatomic particles. She brings real-world research experience to her lectures.", OfficeLocation = "Physics Lab 105" },
            new() { Id = 4, Name = "Prof. Michael Brooks", Title = "Associate Professor", Email = "mbrooks@university.edu", Bio = "Prof. Brooks is a published novelist and literary critic. His work focuses on contemporary American fiction and creative writing pedagogy. He has won several awards for his short stories.", OfficeLocation = "Humanities Building 415" },
            new() { Id = 5, Name = "Dr. Emily Watson", Title = "Professor", Email = "ewatson@university.edu", Bio = "Dr. Watson is a historian specializing in 20th-century global conflicts. She has authored three books on World War II diplomacy and regularly consults for historical documentaries.", OfficeLocation = "Liberal Arts 220" },
            new() { Id = 6, Name = "Dr. James Park", Title = "Assistant Professor", Email = "jpark@university.edu", Bio = "Dr. Park's research centers on molecular biology and gene editing technologies. He completed his postdoctoral work at Stanford and has contributed to breakthroughs in CRISPR applications.", OfficeLocation = "Life Sciences 312" },
            new() { Id = 7, Name = "Dr. Lisa Nguyen", Title = "Professor", Email = "lnguyen@university.edu", Bio = "Dr. Nguyen is a leading researcher in distributed systems and cloud computing. She spent a decade in industry at major tech companies before returning to academia.", OfficeLocation = "Science Building 305" },
            new() { Id = 8, Name = "Dr. David Kim", Title = "Associate Professor", Email = "dkim@university.edu", Bio = "Dr. Kim specializes in statistical analysis and data science. He consults for Fortune 500 companies on predictive modeling and has developed widely-used open-source statistical tools.", OfficeLocation = "Math Hall 215" },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Computer Science", Description = "A foundational course covering the basics of programming, computational thinking, and problem solving. Students learn Python and explore topics including variables, control flow, functions, and basic data structures. No prior programming experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Building 101", MaxEnrollment = 120, CurrentEnrollment = 98, IsFeatured = true, DepartmentId = 1, InstructorId = 1 },
            new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Includes analysis of time and space complexity.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Building 205", MaxEnrollment = 60, CurrentEnrollment = 55, IsFeatured = false, DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, CourseCode = "CS 350", Title = "Operating Systems", Description = "Explore the design and implementation of modern operating systems. Topics include process management, memory management, file systems, concurrency, and security. Hands-on projects using C and Linux.", Credits = 4, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Science Building 310", MaxEnrollment = 45, CurrentEnrollment = 40, IsFeatured = false, DepartmentId = 1, InstructorId = 7 },
            new() { Id = 4, CourseCode = "CS 410", Title = "Machine Learning", Description = "Introduction to machine learning concepts and techniques. Covers supervised and unsupervised learning, neural networks, model evaluation, and practical applications using Python and scikit-learn.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Science Building 301", MaxEnrollment = 40, CurrentEnrollment = 38, IsFeatured = true, DepartmentId = 1, InstructorId = 1 },

            // Mathematics
            new() { Id = 5, CourseCode = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus. Topics include limits, continuity, derivatives, and applications of differentiation. Emphasis on both theory and practical problem-solving skills.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Hall 100", MaxEnrollment = 150, CurrentEnrollment = 130, IsFeatured = true, DepartmentId = 2, InstructorId = 2 },
            new() { Id = 6, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications to computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Hall 105", MaxEnrollment = 80, CurrentEnrollment = 65, IsFeatured = false, DepartmentId = 2, InstructorId = 2 },
            new() { Id = 7, CourseCode = "MATH 310", Title = "Probability and Statistics", Description = "A comprehensive introduction to probability theory and statistical methods. Covers random variables, distributions, hypothesis testing, regression analysis, and Bayesian inference.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Location = "Math Hall 200", MaxEnrollment = 70, CurrentEnrollment = 52, IsFeatured = false, DepartmentId = 2, InstructorId = 8 },

            // Physics
            new() { Id = 8, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Introduction to mechanics, waves, and thermodynamics. Covers Newton's laws, energy conservation, wave motion, and heat transfer. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", Location = "Physics Lab 100", MaxEnrollment = 100, CurrentEnrollment = 88, IsFeatured = false, DepartmentId = 3, InstructorId = 3 },
            new() { Id = 9, CourseCode = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory. Topics include wave-particle duality, the Schrödinger equation, quantum states, operators, and applications to atomic physics.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Physics Lab 200", MaxEnrollment = 35, CurrentEnrollment = 28, IsFeatured = true, DepartmentId = 3, InstructorId = 3 },

            // English
            new() { Id = 10, CourseCode = "ENG 101", Title = "College Composition", Description = "Develop essential academic writing skills through essays, research papers, and peer review. Emphasizes clear argumentation, proper citation, and revision strategies.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Humanities Building 110", MaxEnrollment = 30, CurrentEnrollment = 28, IsFeatured = false, DepartmentId = 4, InstructorId = 4 },
            new() { Id = 11, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Readings include works by Hawthorne, Twain, Fitzgerald, Morrison, and contemporary authors.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Humanities Building 205", MaxEnrollment = 35, CurrentEnrollment = 22, IsFeatured = false, DepartmentId = 4, InstructorId = 4 },

            // History
            new() { Id = 12, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Explore the development of civilizations from ancient Mesopotamia through the late Middle Ages. Examines political, social, cultural, and economic transformations across regions.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", Location = "Liberal Arts 100", MaxEnrollment = 90, CurrentEnrollment = 75, IsFeatured = false, DepartmentId = 5, InstructorId = 5 },
            new() { Id = 13, CourseCode = "HIST 320", Title = "The World Wars", Description = "In-depth analysis of World War I and World War II, examining causes, major campaigns, diplomacy, the home front, and lasting geopolitical consequences.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Liberal Arts 215", MaxEnrollment = 50, CurrentEnrollment = 45, IsFeatured = true, DepartmentId = 5, InstructorId = 5 },

            // Biology
            new() { Id = 14, CourseCode = "BIO 101", Title = "Introduction to Biology", Description = "Survey of biological principles including cell biology, genetics, evolution, ecology, and biodiversity. Includes weekly lab exercises with microscopy and specimen analysis.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Lab Tue 1:00–3:50 PM", Location = "Life Sciences 100", MaxEnrollment = 110, CurrentEnrollment = 95, IsFeatured = false, DepartmentId = 6, InstructorId = 6 },
            new() { Id = 15, CourseCode = "BIO 340", Title = "Molecular Biology", Description = "Study of molecular mechanisms underlying cellular processes. Topics include DNA replication, transcription, translation, gene regulation, and modern techniques such as PCR and CRISPR.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Life Sciences 310", MaxEnrollment = 40, CurrentEnrollment = 33, IsFeatured = true, DepartmentId = 6, InstructorId = 6 },
        };

        // Wire up navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class EnrollmentService
{
    private readonly List<EnrollmentRequest> _requests = new();

    public EnrollmentRequest Submit(EnrollmentRequest request)
    {
        request.SubmittedAt = DateTime.UtcNow;
        request.ConfirmationNumber = $"ENR-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString("N")[..8].ToUpper()}";
        _requests.Add(request);
        return request;
    }

    public EnrollmentRequest? GetByConfirmation(string confirmationNumber) =>
        _requests.FirstOrDefault(r => r.ConfirmationNumber == confirmationNumber);
}

