        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = CatalogService.SearchCourses(Search, DepartmentId);
}

<p class="text-muted">Showing @courses.Count course(s)</p>

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria. Try adjusting your search or filter.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Instructor</th>
                    <th>Enrollment</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td><strong>@course.CourseCode</strong></td>
                        <td>@course.Title</td>
                        <td>@course.Department.Name</td>
                        <td>@course.Credits</td>
                        <td><small>@course.Schedule</small></td>
                        <td>@course.Instructor.Name</td>
                        <td>
                            @course.CurrentEnrollment / @course.MaxEnrollment
                            @if (course.CurrentEnrollment >= course.MaxEnrollment)
                            {
                                <span class="badge bg-danger">Full</span>
                            }
                        </td>
                        <td>
                            <a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject EnrollmentService EnrollmentService
@inject NavigationManager Navigation

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course. You will receive a confirmation number upon submission.</p>

<hr />

@if (!string.IsNullOrEmpty(confirmationNumber))
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted!</h4>
        <p>Your enrollment request has been received. Please save your confirmation number for your records.</p>
        <hr />
        <p class="mb-0"><strong>Confirmation Number:</strong> @confirmationNumber</p>
    </div>
    <a href="/" class="btn btn-outline-primary">Return to Home</a>
    <a href="enroll" class="btn btn-outline-secondary">Submit Another Request</a>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                           value="@Model.StudentName" required maxlength="100" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                           value="@Model.StudentId" required
                           pattern="[A-Z]{1,3}\d{5,9}"
                           title="1-3 uppercase letters followed by 5-9 digits (e.g., CS12345)" />
                    <div class="form-text">Format: 1–3 uppercase letters followed by 5–9 digits (e.g., CS12345)</div>
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                    <select class="form-select" id="courseId" name="Model.CourseId" required>
                        <option value="">-- Select a course --</option>
                        @foreach (var course in CatalogService.GetAllCourses())
                        {
                            <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                                @course.CourseCode — @course.Title (@course.Department.Code)
                            </option>
                        }
                    </select>
                </div>

                <div class="mb-3">
                    <label for="comments" class="form-label">Comments (optional)</label>
                    <textarea class="form-control" id="comments" name="Model.Comments" rows="3"
                              maxlength="500">@Model.Comments</textarea>
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private string? confirmationNumber;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var result = EnrollmentService.Submit(Model);
        confirmationNumber = result.ConfirmationNumber;
    }
}

